136→/// Platform-aware service start command.
137→fn service_start_command(service: &str) -> String {
138→    if cfg!(target_os = "macos") {
139→        format!("brew services start {}", service)
140→    } else {
141→        format!("systemctl start {}", service)
142→    }
143→}
