 1→//! Gap checker for requirement evaluation.
 2→//!
 3→//! The `GapChecker` evaluates whether system-level requirements are met,
 4→//! caching results within a run to avoid redundant command executions.
 5→
 6→use crate::requirements::probe::EnvironmentProbe;
 7→use crate::requirements::registry::{
 8→    InstallContext, Platform, RequirementCheck, RequirementRegistry,
 9→};
10→use crate::requirements::status::{GapResult, RequirementStatus};
11→use crate::steps::resolved::ResolvedStep;
12→use std::collections::{HashMap, HashSet};
13→use std::net::TcpStream;
14→use std::path::{Path, PathBuf};
15→use std::process::Command;
16→use std::time::Duration;
17→
18→/// Checks whether requirements are satisfied on the system.
19→///
20→/// Caches results per-run so the same requirement checked multiple times
21→/// only executes commands once.
22→pub struct GapChecker<'a> {
23→    registry: &'a RequirementRegistry,
24→    probe: &'a EnvironmentProbe,
25→    project_root: PathBuf,
26→    pub(crate) cache: HashMap<String, RequirementStatus>,
27→}
28→
29→impl<'a> GapChecker<'a> {
30→    /// Create a new gap checker.
31→    pub fn new(
32→        registry: &'a RequirementRegistry,
33→        probe: &'a EnvironmentProbe,
34→        project_root: &Path,
35→    ) -> Self {
36→        Self {
37→            registry,
38→            probe,
39→            project_root: project_root.to_path_buf(),
40→            cache: HashMap::new(),
41→        }
42→    }
43→
44→    /// Check all requirements for a step, returning only non-satisfied gaps.
45→    ///
46→    /// `provided_requirements` is authoritative — if the environment says
47→    /// a requirement is provided, skip the check regardless of what the
48→    /// step's requires list says. Until environments exist, callers pass `None`.
49→    pub fn check_step(
50→        &mut self,
51→        step: &ResolvedStep,
52→        provided: Option<&HashSet<String>>,
53→    ) -> Vec<GapResult> {
54→        let mut gaps = Vec::new();
55→        for req_name in &step.requires {
56→            if let Some(provided_set) = provided {
57→                if provided_set.contains(req_name) {
58→                    continue;
59→                }
60→            }
61→
62→            let status = self.check_one(req_name);
63→            if !status.is_satisfied() {
64→                gaps.push(GapResult {
65→                    requirement: req_name.clone(),
66→                    status,
67→                });
68→            }
69→        }
70→        gaps
71→    }
72→
73→    /// Check a single requirement, using cache when available.
74→    pub fn check_one(&mut self, requirement: &str) -> RequirementStatus {
75→        if let Some(cached) = self.cache.get(requirement) {
76→            return cached.clone();
77→        }
78→
79→        let status = self.evaluate(requirement);
80→        self.cache.insert(requirement.to_string(), status.clone());

  1→//! Error types for Bivvy operations.
  2→//!
  3→//! This module defines [`BivvyError`], the primary error type used throughout
  4→//! the application, and a [`Result`] type alias for convenience.
  5→//!
  6→//! # Error Handling Strategy
  7→//!
  8→//! - Use `BivvyError` for domain-specific errors that need distinct handling
  9→//! - Use `anyhow::Error` (via `BivvyError::Other`) for unexpected errors
 10→//! - All errors should provide actionable messages for users
 11→
 12→use std::path::PathBuf;
 13→use thiserror::Error;
 14→
 15→/// Core error type for Bivvy operations.
 16→#[derive(Debug, Error)]
 17→pub enum BivvyError {
 18→    /// Configuration file not found at expected location.
 19→    #[error("Configuration not found: {path}")]
 20→    ConfigNotFound { path: PathBuf },
 21→
 22→    /// Failed to parse configuration file.
 23→    #[error("Failed to parse config at {path}: {message}")]
 24→    ConfigParseError { path: PathBuf, message: String },
 25→
 26→    /// Invalid configuration structure or values.
 27→    #[error("Invalid configuration: {message}")]
 28→    ConfigValidationError { message: String },
 29→
 30→    /// Referenced template does not exist.
 31→    #[error("Unknown template: {name}")]
 32→    UnknownTemplate { name: String },
 33→
 34→    /// Step dependency cycle detected.
 35→    #[error("Circular dependency detected: {cycle}")]
 36→    CircularDependency { cycle: String },
 37→
 38→    /// Step execution failed.
 39→    #[error("Step '{step}' failed: {message}")]
 40→    StepExecutionError { step: String, message: String },
 41→
 42→    /// Shell command failed.
 43→    #[error("Command failed with exit code {code:?}: {command}")]
 44→    CommandFailed { command: String, code: Option<i32> },
 45→
 46→    /// A required tool or service is missing and cannot be auto-installed.
 47→    #[error("Missing requirement '{requirement}': {message}")]
 48→    RequirementMissing {
 49→        requirement: String,
 50→        message: String,
 51→    },
 52→
 53→    /// A requirement check failed unexpectedly (e.g., network error during install).
 54→    #[error("Requirement check failed for '{requirement}': {message}")]
 55→    RequirementCheckFailed {
 56→        requirement: String,
 57→        message: String,
 58→    },
 59→
 60→    /// Shell operation failed (e.g., spawning a debug shell).
 61→    #[error("Shell error: {message}")]
 62→    ShellError { message: String },
 63→
 64→    /// IO error wrapper.
 65→    #[error("IO error: {0}")]
 66→    Io(#[from] std::io::Error),
 67→
 68→    /// Generic wrapped error for anyhow interop.
 69→    #[error(transparent)]
 70→    Other(#[from] anyhow::Error),
 71→}
 72→
 73→/// Result type alias for Bivvy operations.
 74→pub type Result<T> = std::result::Result<T, BivvyError>;
